"""Price lookups for the shop front end."""
from services import backup, primary


class PriceUnavailable(Exception):
    """No service could give a price for the sku."""


_cache = {}


def get_price(sku):
    if sku in _cache:
        return _cache[sku]
    last = None
    for service in (primary, backup):
        try:
            price = service.get_price(sku, timeout=2)
        except Exception as e:  # service error, timeout, unknown sku: try the next one
            last = e
            continue
        _cache[sku] = price
        return price
    raise PriceUnavailable(sku) from last


def clear_cache():
    _cache.clear()
